sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var r = ad.createUserAd({ samAccountName: 'jdoe', upn: 'jdoe@tenant.onmicrosoft.com', displayName: 'J Doe', ou: 'OU=Users' });
  if (!(r && r.ok === true && r.dispatched === true)) {
    stepResult.setFailed('AD-leg createUserAd did not report a successful dispatch: ' + JSON.stringify(r));
    return;
  }
  if (r.hasOwnProperty('accountEnabled') || r.hasOwnProperty('synced')) {
    stepResult.setFailed('AD-leg createUserAd return carries an observation-shaped field (accountEnabled/synced) -- P0-4 regressed: ' + JSON.stringify(r));
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
